<?php require_once __DIR__.'/../config/auth.php';require_role('owner');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo=db();$pdo->prepare('UPDATE users SET name=? WHERE id=?')->execute([trim($_POST['name']),user()['id']]);if(!empty($_POST['password']))$pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),user()['id']]);$_SESSION['user']['name']=trim($_POST['name']);flash('success','Profil diperbarui.');redirect('/owner/profil.php');}$pageTitle='Profil';$active='profil';include __DIR__.'/../includes/header.php';?><section class="card" style="max-width:620px"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label class="field full">Nama<input name="name" value="<?=e(user()['name'])?>" required></label><label class="field full">Username<input value="<?=e(user()['username'])?>" disabled></label><label class="field full">Kata sandi baru<input type="password" name="password"><small class="muted">Kosongkan jika tidak diubah.</small></label><button class="btn primary">Simpan perubahan</button></form></section><?php include __DIR__.'/../includes/footer.php';?>

